using Microsoft.Data.Sqlite;
using MiniPharmacie.Data.Database;

namespace MiniPharmacie.Business.Services;

public sealed class DatabaseBackupService(DatabaseInitializer db)
{
    public async Task<string> CreateVerifiedBackupAsync(long actorId,string? directory=null,CancellationToken ct=default){await using var source=db.CreateConnection();await source.OpenAsync(ct);await SecurityAdministrationService.RequireManager(source,actorId,ct);var folder=directory;if(string.IsNullOrWhiteSpace(folder)){await using var q=source.CreateCommand();q.CommandText="SELECT Value FROM PharmacySettings WHERE Key='BackupDirectory'";folder=(string?)await q.ExecuteScalarAsync(ct);}if(string.IsNullOrWhiteSpace(folder))folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"MiniPharmacie","Sauvegardes");Directory.CreateDirectory(folder);var path=Path.Combine(folder,$"pharmacie-{DateTime.Now:yyyyMMdd-HHmmss}-{Guid.NewGuid():N}.db");await using(var target=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=path,Mode=SqliteOpenMode.ReadWriteCreate,Pooling=false}.ToString())){await target.OpenAsync(ct);source.BackupDatabase(target);await VerifyIntegrityAsync(target,ct);}await VerifyFileAsync(path,ct);await using var audit=source.CreateCommand();audit.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,OccurredAt,Details) VALUES($u,'SAUVEGARDE_CREEE','Database',$d,$p)";audit.Parameters.AddWithValue("$u",actorId);audit.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));audit.Parameters.AddWithValue("$p",path);await audit.ExecuteNonQueryAsync(ct);return path;}
    public async Task RestoreVerifiedBackupAsync(long actorId,string backupPath,CancellationToken ct=default){if(!File.Exists(backupPath))throw new FileNotFoundException("Fichier de sauvegarde introuvable.",backupPath);await VerifyFileAsync(backupPath,ct);await using var active=db.CreateConnection();await active.OpenAsync(ct);await SecurityAdministrationService.RequireManager(active,actorId,ct);var activeUsername=await CurrentUsername(active,actorId,ct);await using(var check=ReadOnly(backupPath)){await check.OpenAsync(ct);await VerifyIntegrityAsync(check,ct);await using var q=check.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Users u JOIN Roles r ON r.Id=u.RoleId WHERE u.Username=$name AND r.Name='Responsable' AND u.IsActive=1";q.Parameters.AddWithValue("$name",activeUsername);if(Convert.ToInt64(await q.ExecuteScalarAsync(ct))!=1)throw new InvalidOperationException("La sauvegarde ne contient pas le compte responsable connecté; restauration refusée.");}
        var safety=await CreateVerifiedBackupAsync(actorId);var stagingPath=db.DatabasePath+".restore-"+Guid.NewGuid().ToString("N");try{await using(var source=ReadOnly(backupPath)){await source.OpenAsync(ct);await using var stage=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=stagingPath,Mode=SqliteOpenMode.ReadWriteCreate,Pooling=false}.ToString());await stage.OpenAsync(ct);source.BackupDatabase(stage);await VerifyIntegrityAsync(stage,ct);}await using(var staged=ReadOnly(stagingPath)){await staged.OpenAsync(ct);staged.BackupDatabase(active);}await VerifyIntegrityAsync(active,ct);await using var audit=active.CreateCommand();audit.CommandText="INSERT INTO AuditLog(UserId,Action,Entity,OccurredAt,Details) VALUES($u,'RESTAURATION_EFFECTUEE','Database',$d,$p)";audit.Parameters.AddWithValue("$u",actorId);audit.Parameters.AddWithValue("$d",DateTimeOffset.Now.ToString("O"));audit.Parameters.AddWithValue("$p",Path.GetFullPath(backupPath));await audit.ExecuteNonQueryAsync(ct);}catch{await using var old=ReadOnly(safety);await old.OpenAsync(ct);old.BackupDatabase(active);await VerifyIntegrityAsync(active,ct);throw;}finally{foreach(var suffix in new[]{"","-wal","-shm"})if(File.Exists(stagingPath+suffix))File.Delete(stagingPath+suffix);}}
    public static async Task VerifyFileAsync(string path,CancellationToken ct=default){await using var c=ReadOnly(path);await c.OpenAsync(ct);await VerifyIntegrityAsync(c,ct);await using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('Users','Sales','Lots','AuditLog')";if(Convert.ToInt64(await q.ExecuteScalarAsync(ct))!=4)throw new InvalidDataException("Le fichier n'est pas une base valide de mini-pharmacie.");}
    private static async Task VerifyIntegrityAsync(SqliteConnection c,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="PRAGMA integrity_check";var result=(string?)await q.ExecuteScalarAsync(ct);if(!string.Equals(result,"ok",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException($"Contrôle SQLite échoué: {result}");}
    private static SqliteConnection ReadOnly(string path)=>new(new SqliteConnectionStringBuilder{DataSource=Path.GetFullPath(path),Mode=SqliteOpenMode.ReadOnly,Pooling=false}.ToString());
    private static async Task<string> CurrentUsername(SqliteConnection c,long id,CancellationToken ct){await using var q=c.CreateCommand();q.CommandText="SELECT Username FROM Users WHERE Id=$u";q.Parameters.AddWithValue("$u",id);return (string?)await q.ExecuteScalarAsync(ct)??throw new UnauthorizedAccessException("Compte responsable invalide.");}
}
